@page "/apply"
@rendermode InteractiveServer
@using sv_c75bf89cacb14705844adedf9d67b5d4.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <!-- Step Indicator Bar -->
    <div class="step-indicator">
        @for (int i = 0; i < _stepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < _currentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@_stepNames[stepIndex]</div>
            </div>
            @if (i < _stepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="error-message">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <textarea id="address" @bind="_address" placeholder="Enter your address"></textarea>
            </div>
            <div class="form-buttons">
                <button class="btn-next" @onclick="NextFromPersonalInfo">Next</button>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="_workEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="_workEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="_workEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="_workEntries[index].EndDate" disabled="@_workEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <input type="checkbox" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="_workEntries[index].Description" placeholder="Describe your responsibilities"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="form-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (_references.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="_references[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="_references[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="_references[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="_references[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="form-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromReferences">Next</button>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" class="cover-letter-textarea" @bind="_coverLetter" @bind:event="oninput" maxlength="2000" placeholder="Tell us why you're a great fit..."></textarea>
                <div class="character-count">@_coverLetter.Length / 2000 characters</div>
            </div>
            <div class="form-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <div class="step-content">
            @if (_submitted)
            {
                <div class="confirmation">
                    <h2>&#10003; Application Submitted!</h2>
                    <p>Your application has been successfully submitted.</p>
                    <p><strong>Application ID: @_applicationId</strong></p>
                </div>
            }
            else
            {
                <h2>Review & Submit</h2>

                <!-- Personal Info Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
                    </div>
                    <dl>
                        <dt>Full Name</dt><dd>@_fullName</dd>
                        <dt>Email</dt><dd>@_email</dd>
                        <dt>Phone</dt><dd>@_phone</dd>
                        <dt>Address</dt><dd>@_address</dd>
                    </dl>
                </div>

                <!-- Work History Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="review-entry">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p>@entry.StartDate.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <!-- References Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var reference in _references)
                    {
                        <div class="review-entry">
                            <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                            <p>@reference.Email | @reference.Phone</p>
                        </div>
                    }
                </div>

                <!-- Cover Letter Review -->
                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    <p class="cover-letter-preview">@_coverLetter</p>
                </div>

                <div class="form-buttons">
                    <button class="btn-back" @onclick="PreviousStep">Back</button>
                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @if (_isSubmitting)
                        {
                            <span>Submitting...</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                </div>
            }
        </div>
    }
</div>

@code {
    private static readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private string _errorMessage = string.Empty;

    // Step 1 - Personal Info
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 - Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string _coverLetter = string.Empty;

    // Step 5 - Submission
    private bool _isSubmitting = false;
    private bool _submitted = false;
    private int _applicationId = 0;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == _currentStep) return "active";
        if (stepIndex < _currentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex < _currentStep)
        {
            _currentStep = stepIndex;
            _errorMessage = string.Empty;
        }
    }

    private void GoToStep(int stepIndex)
    {
        _currentStep = stepIndex;
        _errorMessage = string.Empty;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
            _errorMessage = string.Empty;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        {
            _errorMessage = "Please enter a valid email address.";
            return;
        }

        _currentStep = 1;
    }

    private void NextFromWorkHistory()
    {
        _errorMessage = string.Empty;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _errorMessage = "Please fill in company name, job title, and start date for all positions.";
                return;
            }
        }

        _currentStep = 2;
    }

    private void NextFromReferences()
    {
        _errorMessage = string.Empty;

        foreach (var reference in _references)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        _currentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        _errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }

        _currentStep = 4;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = string.Empty;

        try
        {
            var personalInfo = new PersonalInfo(_fullName, _email, _phone, _address);

            var workEntries = _workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate,
                e.IsCurrent ? null : e.EndDate,
                e.Description ?? string.Empty
            )).ToList();

            var references = _references.Select(r => new Reference(
                r.Name, r.Relationship, r.Email, r.Phone
            )).ToList();

            var application = new JobApplication(personalInfo, new WorkHistory(workEntries), references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
        {
            _workEntries.RemoveAt(index);
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
        {
            _references.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
        {
            _references.RemoveAt(index);
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

