    margin-top: 1.5rem;
    gap: 1rem;
}

.btn-next, .btn-back, .btn-submit, .btn-add, .btn-remove, .btn-edit {
    padding: 0.5rem 1.5rem;
    border: none;
    border-radius: 4px;
