}

.btn-next {
    background: #0d6efd;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover {
    background: #0b5ed7;
}

.btn-back {
    background: #6c757d;
    color: #fff;
}

.btn-back:hover {
    background: #5c636a;
}

.btn-submit {
    background: #198754;
    color: #fff;
    font-weight: 600;
}

.btn-submit:hover:not(:disabled) {
    background: #157347;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: #f8f9fa;
    color: #0d6efd;
    border: 1px dashed #0d6efd;
