    padding: 0.75rem;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #e7f1ff;
}

.btn-remove {
    background: #dc3545;
    color: #fff;
    font-size: 0.85rem;
    padding: 0.3rem 0.75rem;
}

.btn-remove:hover {
    background: #bb2d3b;
}

.btn-edit {
    background: transparent;
    color: #0d6efd;
    text-decoration: underline;
    padding: 0.25rem 0.5rem;
    font-size: 0.9rem;
}

.btn-edit:hover {
    color: #0b5ed7;
}

/* Error Message */
.error-message {
    background: #f8d7da;
    color: #842029;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #f5c2c7;
